functions.claim_next_delivery(shift_value bigint):
CREATE OR REPLACE FUNCTION app_security.claim_next_delivery(shift_value bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE driver_value bigint; branch_value integer; order_value bigint;
BEGIN
    driver_value := app_security.actor_customer_id();
    IF app_security.actor_role() <> 'DRIVER' THEN
        RAISE EXCEPTION 'Driver access is required' USING ERRCODE = '42501';
    END IF;
    SELECT s.branch_id INTO branch_value FROM public.driver_shift s JOIN public.driver_profile p ON p.driver_id = s.driver_id
    WHERE s.shift_id = shift_value AND s.driver_id = driver_value AND s.state = 'ACTIVE' AND p.active
      AND p.branch_id = s.branch_id FOR UPDATE OF s;
    IF branch_value IS NULL THEN
        RAISE EXCEPTION 'Active shift is required' USING ERRCODE = '22023';
    END IF;
    IF EXISTS (SELECT 1 FROM public.delivery_assignment a WHERE a.driver_id = driver_value
            AND a.self_claimed AND a.state IN ('ASSIGNED', 'PICKED_UP')) THEN
        RAISE EXCEPTION 'Finish the claimed delivery first' USING ERRCODE = '22023';
    END IF;
    SELECT o.order_id INTO order_value FROM public.customer_order o
    WHERE o.branch_id = branch_value AND o.order_type = 'delivery'
      AND o.status IN ('Pending', 'Preparing', 'Completed')
      AND NOT EXISTS (SELECT 1 FROM public.delivery_assignment a WHERE a.order_id = o.order_id)
    ORDER BY o.created_at, o.order_id LIMIT 1 FOR UPDATE OF o SKIP LOCKED;
    IF order_value IS NULL THEN RETURN NULL; END IF;
    INSERT INTO public.delivery_assignment(order_id, driver_id, shift_id, branch_id, self_claimed)
    VALUES (order_value, driver_value, shift_value, branch_value, true);
    RETURN order_value;
END $function$

functions.consume_reset(hash_value text, password_:
CREATE OR REPLACE FUNCTION app_security.consume_reset(hash_value text, password_value text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE account_id bigint; token_id bigint; account_email text;
BEGIN
    SELECT customer_id INTO account_id FROM public.password_reset_tokens WHERE token_hash = hash_value;
    IF account_id IS NULL THEN RETURN NULL; END IF;
    PERFORM id FROM public.customers WHERE id = account_id FOR UPDATE;
    SELECT id INTO token_id FROM public.password_reset_tokens
        WHERE token_hash = hash_value AND NOT used AND expires_at > LOCALTIMESTAMP FOR UPDATE;
    IF token_id IS NULL THEN RETURN NULL; END IF;
    UPDATE public.customers SET password = password_value WHERE id = account_id RETURNING email INTO account_email;
    UPDATE public.password_reset_tokens SET used = true WHERE id = token_id;
    DELETE FROM public.password_reset_tokens WHERE customer_id = account_id AND NOT used;
    RETURN account_email;
END $function$

functions.create_reset(email_value text, hash_valu:
CREATE OR REPLACE FUNCTION app_security.create_reset(email_value text, hash_value text, expiry timestamp without time zone)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE account_id bigint; recipient text;
BEGIN
    SELECT id, email INTO account_id, recipient FROM public.customers WHERE email = email_value FOR UPDATE;
    IF account_id IS NULL THEN RETURN NULL; END IF;
    IF hash_value !~ '^[0-9a-f]{64}$' OR expiry <= LOCALTIMESTAMP OR expiry > LOCALTIMESTAMP + interval '31 minutes' THEN
        RAISE EXCEPTION 'Invalid recovery request' USING ERRCODE = '22023';
    END IF;
    DELETE FROM public.password_reset_tokens WHERE customer_id = account_id AND NOT used;
    INSERT INTO public.password_reset_tokens (customer_id, token_hash, expires_at, created_at, used)
    VALUES (account_id, hash_value, expiry, LOCALTIMESTAMP, false);
    RETURN recipient;
END $function$

functions.guard_account_update():
CREATE OR REPLACE FUNCTION app_security.guard_account_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE expected_role text;
BEGIN
    IF current_user = pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid = TG_RELID)) THEN RETURN NEW; END IF;
    IF NEW.id IS DISTINCT FROM OLD.id OR NEW.environment_admin IS DISTINCT FROM OLD.environment_admin THEN
        RAISE EXCEPTION 'Operation is not permitted' USING ERRCODE = '42501';
    END IF;
    IF (NEW.access_level IS DISTINCT FROM OLD.access_level OR NEW.role IS DISTINCT FROM OLD.role)
       AND app_security.actor_role() <> 'SUPER_ADMIN' THEN
        RAISE EXCEPTION 'Operation is not permitted' USING ERRCODE = '42501';
    END IF;
    expected_role := CASE NEW.access_level
        WHEN 1 THEN 'ADMIN' WHEN 2 THEN 'ADMIN' WHEN 3 THEN 'SUPER_ADMIN'
        WHEN 4 THEN 'DRIVER' ELSE 'USER' END;
    IF NEW.role IS DISTINCT FROM expected_role THEN
        RAISE EXCEPTION 'Role and access level are inconsistent' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $function$

functions.guard_delivery_assignment():
CREATE OR REPLACE FUNCTION app_security.guard_delivery_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE order_branch integer; order_type_value text; kitchen_status text;
    shift_driver bigint; shift_branch integer; shift_state text;
BEGIN
    SELECT branch_id, order_type, status INTO order_branch, order_type_value, kitchen_status
    FROM public.customer_order WHERE order_id = NEW.order_id;
    SELECT driver_id, branch_id, state INTO shift_driver, shift_branch, shift_state
    FROM public.driver_shift WHERE shift_id = NEW.shift_id;
    IF order_type_value IS DISTINCT FROM 'delivery' OR NEW.branch_id IS DISTINCT FROM order_branch
       OR NEW.driver_id IS DISTINCT FROM shift_driver OR NEW.branch_id IS DISTINCT FROM shift_branch
       OR shift_state <> 'ACTIVE' THEN
        RAISE EXCEPTION 'Assignment must match a delivery order and driver shift' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'INSERT' AND (NEW.state <> 'ASSIGNED' OR NEW.picked_up_at IS NOT NULL
       OR NEW.delivered_at IS NOT NULL OR kitchen_status NOT IN ('Pending', 'Preparing', 'Completed')) THEN
        RAISE EXCEPTION 'Invalid new assignment' USING ERRCODE = '23514';
    END IF;
    IF TG_OP = 'UPDATE' THEN
        IF NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.branch_id IS DISTINCT FROM OLD.branch_id
           OR OLD.state IN ('DELIVERED', 'CANCELLED') OR NEW.assigned_at IS DISTINCT FROM OLD.assigned_at THEN
            RAISE EXCEPTION 'Assignment history cannot be changed' USING ERRCODE = '42501';
        END IF;
        IF (NEW.driver_id IS DISTINCT FROM OLD.driver_id OR NEW.shift_id IS DISTINCT FROM OLD.shift_id)
           AND (OLD.state <> 'ASSIGNED' OR app_security.actor_role() NOT IN ('ADMIN', 'SUPER_ADMIN')) THEN
            RAISE EXCEPTION 'Only a manager can reassign before pickup' USING ERRCODE = '42501';
        END IF;
        IF app_security.actor_role() = 'DRIVER' AND
           (NEW.driver_id IS DISTINCT FROM OLD.driver_id OR NEW.shift_id IS DISTINCT FROM OLD.shift_id
           OR NEW.self_claimed IS DISTINCT FROM OLD.self_claimed OR NEW.assigned_by IS DISTINCT FROM OLD.assigned_by
           OR (OLD.state = 'ASSIGNED' AND NEW.state NOT IN ('ASSIGNED', 'PICKED_UP'))
           OR (OLD.state = 'PICKED_UP' AND NEW.state NOT IN ('PICKED_UP', 'DELIVERED'))) THEN
            RAISE EXCEPTION 'Invalid driver assignment transition' USING ERRCODE = '42501';
        END IF;
        IF (OLD.state = 'ASSIGNED' AND NEW.state = 'PICKED_UP'
                AND (kitchen_status IS NULL OR kitchen_status NOT IN ('Pending', 'Preparing', 'Completed')
                    OR NEW.picked_up_at IS NULL
                    OR NEW.picked_up_at > now() OR NEW.picked_up_at < now() - interval '1 minute'))
           OR (OLD.state = 'PICKED_UP' AND NEW.state = 'DELIVERED'
                AND (NEW.delivered_at IS NULL OR NEW.delivered_at > now()
                    OR NEW.delivered_at < now() - interval '1 minute'))
           OR (NEW.state <> OLD.state AND NOT (
                OLD.state = 'ASSIGNED' AND NEW.state IN ('PICKED_UP', 'CANCELLED')
                OR OLD.state = 'PICKED_UP' AND NEW.state = 'DELIVERED'))
           OR (NEW.picked_up_at IS DISTINCT FROM OLD.picked_up_at AND NEW.state <> 'PICKED_UP')
           OR (NEW.delivered_at IS DISTINCT FROM OLD.delivered_at AND NEW.state <> 'DELIVERED') THEN
            RAISE EXCEPTION 'Invalid delivery transition' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END $function$

functions.guard_order_relationship():
CREATE OR REPLACE FUNCTION app_security.guard_order_relationship()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE column_name text;
BEGIN
    IF current_user = pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid = TG_RELID)) THEN RETURN NEW; END IF;
    FOREACH column_name IN ARRAY TG_ARGV LOOP
        IF (to_jsonb(NEW) -> column_name) IS DISTINCT FROM (to_jsonb(OLD) -> column_name) THEN
            RAISE EXCEPTION 'Operation is not permitted' USING ERRCODE = '42501';
        END IF;
    END LOOP;
    RETURN NEW;
END $function$

functions.promote_branch_driver(email_value text,:
CREATE OR REPLACE FUNCTION app_security.promote_branch_driver(email_value text, branch_value integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE target_id bigint; current_level smallint;
BEGIN
    IF app_security.actor_role() NOT IN ('ADMIN', 'SUPER_ADMIN')
       OR (app_security.actor_role() = 'ADMIN' AND app_security.actor_branch_id() <> branch_value)
       OR NOT EXISTS (SELECT 1 FROM public.branch WHERE branch_id = branch_value AND active) THEN
        RAISE EXCEPTION 'Driver promotion is not permitted' USING ERRCODE = '42501';
    END IF;
    SELECT id, access_level INTO target_id, current_level FROM public.customers
    WHERE lower(email) = lower(btrim(email_value)) AND NOT environment_admin FOR UPDATE;
    IF target_id IS NULL OR current_level <> 0 THEN
        RAISE EXCEPTION 'Registered customer account is required' USING ERRCODE = '22023';
    END IF;
    UPDATE public.customers SET role = 'DRIVER', access_level = 4 WHERE id = target_id;
    INSERT INTO public.driver_profile(driver_id, branch_id) VALUES(target_id, branch_value);
    RETURN target_id;
END $function$

functions.validate_special_selection_relationship(:
CREATE OR REPLACE FUNCTION app_security.validate_special_selection_relationship()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE special_order_id bigint; selected_order_id bigint;
BEGIN
    SELECT s.order_id INTO special_order_id
    FROM public.order_special_item s
    WHERE s.order_special_item_id = NEW.order_special_item_id;
    IF NEW.order_menu_item_id IS NOT NULL THEN
        SELECT m.order_id INTO selected_order_id FROM public.order_menu_item m
        WHERE m.order_menu_item_id = NEW.order_menu_item_id;
    ELSE
        SELECT p.order_id INTO selected_order_id FROM public.order_pizza_item p
        WHERE p.order_pizza_item_id = NEW.order_pizza_item_id;
    END IF;
    IF special_order_id IS NULL OR selected_order_id IS NULL OR special_order_id <> selected_order_id THEN
        RAISE EXCEPTION 'Special selection must reference an item from the same order' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END $function$

functions.verified_customer_id():
CREATE OR REPLACE FUNCTION app_security.verified_customer_id()
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    candidate bigint;
    signing_key text;
    supplied_signature text;
    expected_signature text;
    payload text;
BEGIN
    BEGIN
        candidate := nullif(current_setting('app.customer_id', true), '')::bigint;
    EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
        RETURN NULL;
    END;
    supplied_signature := nullif(current_setting('app.context_signature', true), '');
    IF candidate IS NULL OR candidate <= 0 OR supplied_signature IS NULL THEN
        RETURN NULL;
    END IF;
    SELECT s.secret INTO signing_key
    FROM app_security.rls_context_secret s
    WHERE s.singleton;
    IF signing_key IS NULL THEN RETURN NULL; END IF;
    payload := 'rls-context-v1|' || candidate::text || '|' || pg_backend_pid()::text
        || '|' || pg_current_xact_id()::text;
    expected_signature := encode(public.hmac(payload, signing_key, 'sha256'), 'hex');
    IF supplied_signature <> expected_signature THEN RETURN NULL; END IF;
    RETURN candidate;
END $function$

functions.verified_environment_admin():
CREATE OR REPLACE FUNCTION app_security.verified_environment_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
    signing_key text;
    supplied_signature text;
    expected_signature text;
    payload text;
BEGIN
    IF current_setting('app.environment_admin', true) IS DISTINCT FROM 'true' THEN
        RETURN false;
    END IF;
    supplied_signature := nullif(current_setting('app.context_signature', true), '');
    IF supplied_signature IS NULL THEN RETURN false; END IF;
    SELECT s.secret INTO signing_key FROM app_security.rls_context_secret s WHERE s.singleton;
    IF signing_key IS NULL THEN RETURN false; END IF;
    payload := 'rls-context-v1|environment-admin|' || pg_backend_pid()::text
        || '|' || pg_current_xact_id()::text;
    expected_signature := encode(public.hmac(payload, signing_key, 'sha256'), 'hex');
    RETURN supplied_signature = expected_signature;
END $function$
